import {fmt,sortSegs,dedupe,activeSeg,activeSlide,scoreQ} from "/core.mjs";
import { requestJson as J, uploadFile as xput, fileExtension as ext } from "/api-client.mjs";
/* ---------- Server-backed lecture workspace ---------- */
let DUR=0;
let slides=[];
let quiz0=[];
/* ---------- State ---------- */
const S={view:"dash",loaded:false,segs:[],trans:[],notes:[],time:0,playing:false,rate:1,pane:"tr",q:"",quiz:{i:0,ans:{},done:false},attempts:[],pending:null,revision:null,whyWrong:{},returnToQuizReview:false,textBased:false,radar:{loading:false,error:"",data:null},coach:{loading:false,error:"",data:null}};
try{S.attempts=JSON.parse(localStorage.getItem("ls_att")||"[]")}catch(e){}
const IC={"live":"M12 3a3 3 0 00-3 3v6a3 3 0 006 0V6a3 3 0 00-3-3zM5 11a7 7 0 0014 0M12 18v3","settings":"M12 8a4 4 0 100 8 4 4 0 000-8zM12 2v3M12 19v3M2 12h3M19 12h3M4.9 4.9l2.1 2.1M17 17l2.1 2.1M4.9 19.1L7 17M17 7l2.1-2.1","dash": "M3 3h7v9H3zM14 3h7v5h-7zM14 12h7v9h-7zM3 16h7v5H3z", "lib": "M4 5h16M4 12h16M4 19h10", "up": "M12 16V4m0 0l-4 4m4-4l4 4M4 20h16", "ws": "M3 5h18v12H3zM8 21h8", "notes": "M6 3h9l3 3v15H6zM9 11h6M9 15h6", "quiz": "M9 9a3 3 0 115 2c-1 1-2 1.5-2 3M12 18h.01M12 3a9 9 0 100 18 9 9 0 000-18z","radar":"M3 12a9 9 0 1018 0 9 9 0 00-18 0zm9-6v6l4 2","coach":"M12 3a9 9 0 100 18 9 9 0 000-18zm-3 7h6m-6 4h4m-4 4h2"};
const ic=k=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${IC[k]}"/></svg>`;
const ST={completed:["g","✓","Completed"],completed_with_warnings:["u","⚠","Completed with warnings"],needs_transcript:["u","⚠","Needs transcript"],processing:["p","◔","Processing"],failed:["e","✕","Failed"],created:["","•","Not processed"]};
const stTag=s=>{const t=ST[s]||["","•",String(s)];
return `<span class="tag ${t[0]}">${t[1]} ${t[2]}</span>`};
const isSemanticMatch=x=>String(x?.source||"").includes("semantic_embedding_match");
const transitionThreshold=x=>{if(!isSemanticMatch(x))return .7;const m=/min_similarity=([0-9.]+)/.exec(String(x.source||""));return m?Math.max(.05,Math.min(.95,Number(m[1])||.35)):.35};
const transitionUncertain=x=>x.timestamp==null||Number(x.confidence||0)<transitionThreshold(x);
const transitionScoreLabel=x=>isSemanticMatch(x)?"cosine similarity":"confidence";
const transitionMethodLabel=x=>isSemanticMatch(x)?"Semantic match":String(x?.source||"").includes("transcript_match")?"Text-overlap match":String(x?.source||"")==="transcript_section_marker"?"Transcript-derived section":String(x?.source||"").startsWith("manual")?"Manual timing":String(x?.source||"Inferred");
const slBadge=(x,un)=>x.source==="curated section marker"?`<span class="tag">Section marker</span>`:x.source==="transcript_section_marker"?`<span class="tag">Transcript section</span>`:String(x.source).startsWith("manual")?`<span class="tag g">✓ Confirmed (manual)</span>`:x.timestamp==null?`<span class="tag u">⚠ No timestamp</span>`:un?`<span class="tag u">⚠ Uncertain, inferred</span>`:`<span class="tag">≈ Inferred</span>`;
function tlHtml(){if(!DUR)return "";
const pc=t=>(t/DUR*100).toFixed(2)+"%";
const segs=S.segs.map(g=>{const w=Math.max(g.processingStatus==="completed"?.4:.9,(g.endTime-g.startTime)/DUR*100).toFixed(2);return `<i class="tseg ${g.processingStatus==="completed"?"":"bad"}" style="left:${pc(g.startTime)};width:${w}%" title="${g.processingStatus==="completed"?"Lesson text":"Source text unavailable"}"></i>`}).join("");
const mk=S.trans.filter(t=>t.timestamp!=null).map(t=>{const sl=slides.find(s=>s.id===t.slideId),k=t.source==="curated section marker"?"c":String(t.source).startsWith("manual")?"c":transitionUncertain(t)?"u":"i",w=t.source==="curated section marker"?"section marker":k==="c"?"confirmed":k==="u"?"lower-evidence inferred":"inferred";const score=`${transitionScoreLabel(t)} ${Math.round(t.confidence*100)}%`,label=S.sectionMode?"Section":"Slide";return `<button class="mk ${k}" style="left:${pc(t.timestamp)}" data-seek="${t.timestamp}" aria-label="${label} ${sl?sl.n:"?"} at ${fmt(t.timestamp)}, ${w}" title="${label} ${sl?sl.n:"?"} · ${fmt(t.timestamp)} · ${w} · ${score}">${sl?sl.n:""}</button>`}).join("");
const nm=S.notes.map(n=>`<button class="nm" style="left:${pc(n.t)}" data-seek="${n.t}" aria-label="Note at ${fmt(n.t)}" title="Note · ${fmt(n.t)}"></button>`).join("");
return `<div class="utl" role="group" aria-label="Lecture timeline"><div class="lane">${segs}<b id="tlph" class="tph"></b></div><div class="lane">${mk}</div><div class="lane">${nm}</div><div class="leg"><span>▮ Transcript (amber = failed)</span><span>● Slide / section: ✓ confirmed · ≈ inferred · ⚠ uncertain (dashed)</span><span>◆ Note</span></div></div>`}
const hl=t=>{const q=(S.q||"").trim();
if(!q)return esc(t);
return t.split(new RegExp("("+q.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+")","gi")).map((x,i)=>i%2?`<mark>${esc(x)}</mark>`:esc(x)).join("")};
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
function toast(x){const t=$("#t");t.textContent=x;t.hidden=false;clearTimeout(toast.h);toast.h=setTimeout(()=>t.hidden=true,2200)}
async function go(v){
 if(v==="radar")return openRadar();
 if(v==="coach")return openCoach();
 if(v==="quiz"&&!S.loaded){
  try{
   const list=await J("/api/lectures");S.list=list;S.server=true;
   const candidate=list.find(x=>x.questions>0)||list.find(x=>x.status==="completed"||x.status==="completed_with_warnings")||list[0];
   if(candidate)await openLecture(candidate.id,false);
  }catch(e){toast("Could not load your saved lecture: "+e.message);return}
 }
 S.view=v;render();
}


async function refresh(){try{S.health=await J("/api/health");S.list=await J("/api/lectures");S.server=true;if(S.list.length&&!S.loaded){await openLecture(S.list[0].id,false)}}catch(e){S.server=false;S.list=[]}if(!S.up||!S.up.busy)render()}
async function openLecture(id,go_=true){const L=await J("/api/lectures/"+id);S.mode="server";S.lid=id;S.title=L.title;S.status=L.status;S.msg=L.stages.transcribe&&L.stages.transcribe.state==="blocked"?L.stages.transcribe.msg:"";
 slides=L.slides.map(x=>({id:x.id,n:x.slideNumber,title:x.title,text:x.text,img:x.hasImage,kind:x.processingStatus}));S.sectionMode=slides.length>0&&slides.every(x=>x.kind==="transcript_section");S.segs=L.segments;S.trans=L.transitions.map(t=>({...t,id:t.slideId}));
 S.notes=L.notes.map(n=>({id:n.id,t:n.startTime,slide:n.slideId,type:n.type,src:n.source,text:n.text}));quiz0=L.questions.map(q=>({id:q.id,type:q.type,q:q.question,opts:q.options,answer:q.answer,exp:q.explanation,t:q.startTime,slideId:q.slideId,segmentIds:q.segmentIds||[],topic:q.topic}));
 DUR=L.duration||0;S.report=L.report;S.errors=L.errors;S.textBased=!!L.isTextLesson;S.loaded=true;S.time=0;S.playing=false;S.quiz={i:0,ans:{},done:false};S.revision=null;S.whyWrong={};S.returnToQuizReview=false;
 S.media=L.hasMedia?{url:`/api/lectures/${id}/media`,video:L.hasVideo}:null;if(go_)go("ws")}
async function openRadar(){S.view="radar";S.radar.loading=true;S.radar.error="";render();try{S.radar.data=await J("/api/revision-radar")}catch(e){S.radar.error=e.message}finally{S.radar.loading=false;if(S.view==="radar")render()}}
async function openCoach(){S.view="coach";S.coach.loading=true;S.coach.error="";render();try{S.coach.data=await J("/api/learning-coach")}catch(e){S.coach.error=e.message}finally{S.coach.loading=false;if(S.view==="coach")render()}}
function coachDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`}
function coachDoneList(){try{return JSON.parse(localStorage.getItem(`ll_coach_done_${coachDate()}`)||"[]").map(String)}catch(_){return[]}}
function toggleCoachDone(id){const list=coachDoneList(),key=String(id),i=list.indexOf(key);if(i>=0)list.splice(i,1);else list.push(key);try{localStorage.setItem(`ll_coach_done_${coachDate()}`,JSON.stringify(list))}catch(_){}render()}
async function startRevision(id,topic){try{const focus=await J(`/api/lectures/${id}/revision?topic=${encodeURIComponent(topic)}`);await openLecture(id,false);
  S.revision=focus;quiz0=focus.questions.map(q=>({id:q.id,type:q.type,q:q.question,opts:q.options||[],answer:q.answer,exp:q.explanation,t:q.startTime,slideId:q.slideId,segmentIds:q.segmentIds||[],topic:q.topic}));
  S.quiz={i:0,ans:{},done:false};S.whyWrong={};S.pane="tr";S.view="ws";render();toast(`Revision focus: ${topic}`)}catch(e){toast(e.message)}}
function reportServer(){const r=S.report,f=x=>x==null?"—":fmt(x);return `<table><tr><td>${S.textBased?"Study sequence":"Recording duration"}</td><td>${f(r.duration)}${S.textBased?" (section markers)":""}</td></tr><tr><td>Transcript segments</td><td>${r.segmentsCompleted} completed, ${r.segmentsFailed} failed</td></tr><tr><td>Transcript range</td><td>${f(r.firstSegment)} – ${f(r.lastSegment)}</td></tr><tr><td>Failed intervals</td><td>${r.failedIntervals.map(i=>f(i[0])+"–"+f(i[1])).join(", ")||"none known"}</td></tr><tr><td>${S.sectionMode?"Lecture sections generated":"Slides extracted"}</td><td>${r.slides}</td></tr><tr><td>Transitions</td><td>${r.timedTransitions} timed, ${r.uncertainTransitions} uncertain or untimed</td></tr><tr><td>Alignment method</td><td>${esc(r.alignmentMode)}</td></tr><tr><td>Notes / quiz questions</td><td>${r.notes} / ${r.questions}</td></tr><tr><td>Status</td><td><span class="tag ${r.status==="completed"?"g":"u"}">${esc(r.status)}</span></td></tr></table>${(S.errors||[]).length?`<h2 style="margin-top:10px">Processing errors</h2>`+S.errors.map(e=>`<p class="sub">${esc(e.stage)}: ${esc(e.message)}</p>`).join(""):""}`}


const STG=["verify","inspect","slides","transcribe","audio","align","notes","quiz","validate"];
async function poll(id){for(;;){const L=await J("/api/lectures/"+id);const el=$("#ups");if(el)el.innerHTML=upStatus(L);if(L.status==="failed"){S.up.busy=false;const g=$("#go");if(g)g.disabled=false;toast("Processing failed at stage: "+L.stage);return}if(L.status!=="processing"){S.up.busy=false;await refresh();await openLecture(id,false);S.view="ws";render();toast("Processing finished: "+L.status);return}await new Promise(r=>setTimeout(r,1000))}}
async function startUpload(){if(S.up&&S.up.busy)return;const f=S.files||{};const log=m=>{S.up.log.push(m);$("#ups").innerHTML=upStatus()};
 try{S.up={busy:true,log:[]};$("#go").disabled=true;const title=$("#ti").value.trim();if(!title||!f.media)throw new Error("Add a lecture recording and title. Slides and transcript are optional.");
  const qc=+$("#qc").value;const {id}=await J("/api/lectures",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({title,subject:$("#su").value,quizCount:qc})});S.up.lid=id;
  const m=await xput(`/api/lectures/${id}/media?ext=${ext(f.media)}`,f.media,p=>{$("#pg").value=p*100});log(`Recording stored: ${fmt(m.duration)} ${m.video?"video":"audio-only"}`);
  if(f.slides){const sd=await xput(`/api/lectures/${id}/slides?ext=${ext(f.slides)}`,f.slides);log("Slides stored"+(sd.pages?`: ${sd.pages} pages`:""));}else log("No slides supplied; LectureLens AI will create sections from the transcript.");
  if(f.tr){const t=await xput(`/api/lectures/${id}/transcript?ext=${ext(f.tr)}`,f.tr);log(`Transcript file stored: ${t.segments} cues (supplied by you, not generated)`)}
  await J(`/api/lectures/${id}/process`,{method:"POST"});log("Processing started");poll(id)}catch(e){S.up.busy=false;const g=$("#go");if(g)g.disabled=false;log("Error: "+e.message);toast(e.message)}}
function loop(){const m=$("#med");if(m&&S.view==="ws"&&S.mode==="server"&&Math.abs(S.time-m.currentTime)>0.01){S.time=m.currentTime;sync()}requestAnimationFrame(loop)}
/* ---------- Playback and section navigation ---------- */
let last=0,raf=0;
function tick(n){if(!S.playing)return;S.time=Math.min(DUR,S.time+(n-last)/1000*S.rate);last=n;if(S.time>=DUR)S.playing=false;sync();raf=requestAnimationFrame(tick)}
function play(){if(S.time>=DUR)S.time=0;S.playing=!S.playing;if(S.playing){last=performance.now();raf=requestAnimationFrame(tick)}render()}
function seek(t){S.time=Math.max(0,Math.min(DUR,t));const m=$("#med");if(m)m.currentTime=S.time;sync()}
function sync(){const s=activeSeg(S.segs.filter(x=>x.processingStatus==="completed"),S.time),a=activeSlide(S.trans,S.time);const cur=$("#cur");if(!cur)return;const ph=$("#tlph");if(ph&&DUR)ph.style.left=(S.time/DUR*100)+"%";cur.textContent=fmt(S.time);$("#bar").value=S.time;
document.querySelectorAll(".seg").forEach(b=>{const on=s&&b.dataset.id===s.id;if(on&&!b.classList.contains("on"))b.scrollIntoView({block:"nearest"});b.classList.toggle("on",!!on)});
document.querySelectorAll(".slide").forEach(b=>b.classList.toggle("on",!!a&&b.dataset.id===a.slideId));
const sl=slides.find(x=>a&&x.id===a.slideId)||slides[0];$("#stg").innerHTML=`<h3>${S.sectionMode?"Section":"Slide"} ${sl.n}. ${esc(sl.title)}</h3>`+(S.lid&&sl.img?`<img src="/api/lectures/${S.lid}/slide-image/${sl.n}" alt="Slide ${sl.n}" style="max-width:100%;border-radius:8px;background:#fff">`:`<pre>${esc(sl.text)}</pre>`);
const pb=$("#pp");if(pb)pb.textContent=S.playing?"Pause":"Play"}
/* ---------- Export ---------- */
function dl(name,mime,body){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([body],{type:mime}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
const exMD=()=>`# ${S.title||"Lecture notes"}\n\n`+S.notes.map(n=>`## ${fmt(n.t)} · ${n.type}\n${n.text}\n`).join("\n");
const exTXT=()=>S.segs.filter(s=>s.processingStatus==="completed").map(s=>`[${fmt(s.startTime)}] ${s.text}`).join("\n");
function exportNotesPdf(){
 const win=window.open("","_blank");if(!win){toast("Allow pop-ups to export your notes as PDF.");return}
 const title=String(S.title||"Lecture notes");
 const escPdf=x=>String(x??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
 const progress=readNotesProgress(),reviewed=new Set(progress.reviewed);
 const content=S.notes.map((n,i)=>{
   const sl=slides.find(x=>x.id===n.slide),v=noteSvg(n),parts=noteParts(n),isReviewed=reviewed.has(String(n.id));
   const sourceLabel=S.sectionMode?"Section":"Slide";const srcImage=S.mode==="server"&&S.lid&&sl?.img?`<img class="source-img" src="${location.origin}/api/lectures/${encodeURIComponent(S.lid)}/slide-image/${sl.n}" alt="Original source slide ${sl.n}">`:"";
   const points=parts.points.length?`<section class="points"><div class="kicker">KEY POINTS</div><ul>${parts.points.map(x=>`<li>${escPdf(x)}</li>`).join("")}</ul></section>`:"";
   const example=parts.example?`<section class="extra example"><div class="kicker">WORKED EXAMPLE FROM THE SOURCE</div><p>${escPdf(parts.example)}</p></section>`:"";
   const caution=parts.caution?`<section class="extra caution"><div class="kicker">IMPORTANT DISTINCTION</div><p>${escPdf(parts.caution)}</p></section>`:"";
   return `<article class="note"><div class="meta">NOTE ${String(i+1).padStart(2,"0")} · ${escPdf(fmt(n.t))} · ${escPdf(n.type)}${sl?` · ${sourceLabel} ${sl.n}`:""} · ${isReviewed?"Reviewed":"Not yet reviewed"}</div><h2>${escPdf(parts.heading)}</h2><div class="body-grid"><section class="explain"><div class="kicker">CORE EXPLANATION</div><p>${escPdf(parts.main)}</p>${points}${example}${caution}</section><section class="diagram"><div class="kicker">VISUAL GUIDE${sl?.img?" + SOURCE SLIDE":""}</div>${srcImage}${v.svg}<p class="caption">${escPdf(v.caption)}</p></section></div><p class="source">Source: ${escPdf(n.src||"lecture material")} · ${sl?`${sourceLabel} ${sl.n}`:"Lecture note"} · ${escPdf(fmt(n.t))}</p></article>`;
 }).join("");
 const reviewedCount=S.notes.filter(n=>reviewed.has(String(n.id))).length;
 win.document.open();
win.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${escPdf(title)} · Study Notes</title><style>@page{size:A4;margin:14mm 14mm 18mm}*{box-sizing:border-box}body{font:10.5px/1.65 Inter,Arial,sans-serif;color:#17213a;margin:0;background:#fff}.cover{padding:30px 28px 24px;background:#111b38;color:#fff;border-radius:16px;margin:0 0 22px;min-height:205px;position:relative;overflow:hidden;break-after:page;page-break-after:always}.cover:after{content:"";position:absolute;width:230px;height:230px;border:1px solid rgba(255,255,255,.16);border-radius:50%;right:-55px;top:-75px;box-shadow:0 0 0 24px rgba(255,255,255,.035),0 0 0 52px rgba(255,255,255,.025)}.brand{font-size:9px;letter-spacing:2.2px;font-weight:800;color:#a99cff}.cover h1{font-size:31px;line-height:1.18;margin:15px 0 9px;max-width:78%;letter-spacing:-.7px}.cover p{color:#d5dcef;margin:0;max-width:78%}.cover-stats{display:flex;gap:9px;flex-wrap:wrap;margin-top:22px;color:#e0e6f4;font-size:9px}.cover-stats span{padding:7px 10px;border:1px solid rgba(255,255,255,.18);border-radius:8px;background:rgba(255,255,255,.07)}.cover-stats b{color:#fff}.cover .concept-index{position:relative;z-index:1;margin:22px 0 0;padding:13px 15px;border:1px solid rgba(255,255,255,.18);border-radius:10px;background:rgba(255,255,255,.07);color:#fff}.cover .concept-index h2{font-size:13px;color:#fff}.cover .concept-index li{color:#e2e8f5}.note{border:1px solid #dce2ee;border-left:4px solid #7665df;border-radius:12px;padding:16px 17px;margin:0 0 15px;break-inside:avoid;page-break-inside:avoid;box-shadow:0 3px 12px rgba(25,38,72,.045)}.meta,.kicker{font-size:8px;font-weight:800;letter-spacing:1.15px;color:#7161d4;text-transform:uppercase}.note h2{font-size:17px;line-height:1.3;margin:6px 0 12px;color:#17213a}.body-grid{display:grid;grid-template-columns:1.12fr .88fr;gap:11px}.explain,.diagram{border:1px solid #e3e7f0;border-radius:10px;padding:12px;background:#f8f9fd;min-width:0}.explain>p{margin:7px 0 0;white-space:pre-wrap;line-height:1.72}.diagram{background:#f5f4ff}.diagram svg{width:100%;height:auto;max-height:175px}.source-img{width:100%;max-height:125px;object-fit:contain;margin-bottom:7px}.caption{font-size:8px;color:#5c6680}.points{margin-top:13px;padding-top:10px;border-top:1px solid #e2e5ef}.points ul{padding-left:17px;margin:7px 0 0}.points li{margin:5px 0;color:#35415c}.points li::marker{color:#7665df}.extra{margin-top:10px;padding:9px 10px;border:1px solid #dfe3ec;border-radius:8px}.extra p{margin:4px 0 0}.example{background:#eff9f5;border-color:#cce8dc}.caution{background:#fff8e9;border-color:#f2dfb2}.source{font-size:8px;color:#70798b;margin:10px 0 0;padding-top:7px;border-top:1px dashed #e0e4ec}.concept-index,.question-bank{margin:16px 0;padding:14px 16px;border:1px solid #dfe3ec;border-radius:11px;background:#fbfbfe}.concept-index h2,.question-bank h2{font-size:17px;margin:0 0 8px}.concept-index ul{columns:2;padding-left:18px;margin:0}.concept-index li{margin:3px 0}.pdf-question{padding:10px 0;border-top:1px solid #e6e8ef;break-inside:avoid}.pdf-question ol{margin:5px 0 5px;padding-left:24px}.pdf-question p{margin:4px 0}.footer{margin-top:17px;border-top:1px solid #e2e5ed;padding-top:9px;color:#7a8292;font-size:8px}@media print{.note{break-inside:avoid}body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}

</style></head><body><main><header class="cover"><div class="brand">LECTURELENS AI · VISUAL STUDY GUIDE</div><h1>${escPdf(title)}</h1><p>Explanations, key points, diagrams and references from the available lecture material.</p><div class="cover-stats"><span><b>${S.notes.length}</b> study notes</span><span><b>${reviewedCount}/${S.notes.length}</b> reviewed</span><span><b>${new Date().toLocaleDateString()}</b> exported</span></div>${S.notes.length?`<section class="concept-index"><h2>Important concepts at a glance</h2><ul>${S.notes.map(n=>`<li>${escPdf(noteParts(n).heading)}</li>`).join("")}</ul></section>`:""}</header>${content}${quiz0.length?`<section class="question-bank"><h2>Important practice questions</h2>${quiz0.map((q,i)=>`<article class="pdf-question"><b>Q${i+1}. ${escPdf(q.q)}</b>${(q.opts||[]).length?`<ol type="A">${q.opts.map(o=>`<li>${escPdf(o)}</li>`).join("")}</ol>`:""}<p><b>Answer:</b> ${escPdf(q.answer||"See lecture notes")}</p>${q.exp?`<p>${escPdf(q.exp)}</p>`:""}</article>`).join("")}</section>`:""}<footer class="footer">Prepared in LectureLens AI. Verify important details against the cited lecture source. AI-assisted content may require review.</footer></main></body></html>`);
win.document.close();
const imgs=[...win.document.images];
Promise.all(imgs.map(i=>i.complete?Promise.resolve():new Promise(r=>{i.onload=r;i.onerror=r}))).then(()=>setTimeout(()=>win.print(),350));
}
/* ---------- Views ---------- */
function report(){if(S.mode==="server"&&S.report)return reportServer();
const ok=S.segs.filter(s=>s.processingStatus==="completed"),bad=S.segs.filter(s=>s.processingStatus!=="completed"),unc=S.trans.filter(x=>x.timestamp==null||x.confidence<.7);
return `<table><tr><td>Study sequence</td><td>${fmt(DUR)} (section markers)</td></tr><tr><td>Transcript segments</td><td>${ok.length} completed, ${bad.length} failed</td></tr><tr><td>Transcript range</td><td>${fmt(ok[0].startTime)} – ${fmt(ok[ok.length-1].endTime)}</td></tr><tr><td>Failed interval</td><td>${bad.map(b=>"≈"+fmt(b.startTime)).join(", ")||"none"} (kept as a flagged gap)</td></tr><tr><td>Slides extracted</td><td>${slides.length}</td></tr><tr><td>Transitions</td><td>${S.trans.filter(x=>x.timestamp!=null).length} timed, ${unc.length} uncertain</td></tr><tr><td>Notes / quiz questions</td><td>${S.notes.length} / ${quiz0.length}</td></tr><tr><td>Status</td><td><span class="tag u">completed with warnings</span></td></tr></table>`}
const priorityClass=p=>{const v=String(p||"").toLowerCase();
return v==="high priority"?"high":v==="needs practice"?"practice":v==="improving"?"improving":v==="not assessed"?"practice":"strong"};
function revisionFocus(){if(!S.revision)return"";
const r=S.revision,p=r.performance,refs=r.references||{};
 const sourceKind=S.sectionMode?"Section":"Slide";const lectureTitle=r.lecture?.title||S.title||"Current lecture";const performance=r.performance||{accuracy:null,correct:0,incorrect:0,priority:"Not assessed"};const slideHtml=(refs.slides||[]).map(s=>s.id?`<button class="btn" data-revslide="${esc(s.id)}">${sourceKind} ${s.slideNumber??"?"}: ${esc(s.title||"Lecture source")}</button>`:`<span class="tag">${sourceKind} ${s.slideNumber??"?"}: ${esc(s.title||"Lecture source")} · previous source</span>`).join(" ");
 const segmentHtml=(refs.segments||[]).map(s=>`<div class="rev-source"><button class="btn" data-revseek="${s.startTime}">${fmt(s.startTime)}</button> ${esc(s.text.slice(0,260))}</div>`).join("");
 const timestampHtml=(refs.timestamps||[]).map(t=>`<button class="btn" data-revseek="${t.startTime}">Recorded question source · ${fmt(t.startTime)}${t.slideNumber?` · slide ${t.slideNumber}`:""}</button>`).join(" ");
 const noteHtml=(refs.notes||[]).map(n=>`<div class="rev-source"><button class="btn" data-j="${n.startTime}">${fmt(n.startTime)}</button> <span class="tag">${esc(n.type)}</span><p>${esc(n.text.slice(0,260))}</p></div>`).join("");
 return `<section class="card rev-focus" aria-labelledby="revision-focus-title"><div class="rev-focus-head"><div><h2 id="revision-focus-title">Revision focus: ${esc(r.topic||"Selected topic")}</h2><p class="sub" style="margin:4px 0 0">${esc(lectureTitle)} · ${performance.accuracy==null?"Not assessed":performance.accuracy+"% accuracy"} · ${performance.correct||0} correct / ${performance.incorrect||0} incorrect answers</p></div><span class="priority ${priorityClass(performance.priority)}">${esc(performance.priority||"Not assessed")}</span></div>
 ${slideHtml?`<div class="rev-source"><b>${S.sectionMode?"Related lecture sections":"Related slides"}</b><div class="row" style="margin-top:7px">${slideHtml}</div></div>`:""}
 ${segmentHtml?`<div class="rev-source"><b>Transcript segments</b>${segmentHtml}</div>`:""}
 ${timestampHtml?`<div class="rev-source"><b>Saved question source times</b><div class="row" style="margin-top:7px">${timestampHtml}</div></div>`:""}
 ${noteHtml?`<div class="rev-source"><b>Related notes</b>${noteHtml}</div>`:""}
 ${!slideHtml&&!segmentHtml&&!timestampHtml&&!noteHtml?`<p class="rev-empty">No current transcript, note, or slide references were available for this topic.</p>`:""}
 <div class="row" style="margin-top:10px"><button class="btn p" id="revquiz" ${(r.questions||[]).length?"":"disabled"}>Practice ${(r.questions||[]).length} existing related question${(r.questions||[]).length===1?"":"s"}</button><span class="rev-empty">${(r.questions||[]).length?`Questions are filtered to this source topic.`:"No existing quiz questions are currently tagged to this topic."}</span></div></section>`
}
