 if(/normalisation|normalization/.test(text)) return {label:"Normalisation overview",caption:"The lecture describes organising related data to reduce unnecessary repetition and update anomalies.",svg:svg(`${box(8,57,142,76,"REPEATED DATA","Unnecessary duplication","#d79b36")}${arrow(150,95,188,95)}${box(191,57,142,76,"RELATED TABLES","Organised structure","#6d5dfc")}${arrow(333,95,371,95)}${box(374,57,138,76,"FEWER ANOMALIES","Less repetition","#2d9d78")}`)};
 if(/cpu schedul|scheduling criteria|response time|turnaround time/.test(text)) return {label:"CPU scheduling criteria",caption:"The lecture compares scheduling methods using measures such as utilisation, throughput, waiting time and response time.",svg:svg(`${box(12,27,152,56,"UTILISATION","Keep the CPU busy","#6d5dfc")}${box(184,27,152,56,"THROUGHPUT","Work completed","#2d9d78")}${box(356,27,152,56,"TURNAROUND","Total completion time","#d79b36")}${box(98,106,152,56,"WAITING TIME","Time in the ready queue","#d79b36")}${box(270,106,152,56,"RESPONSE TIME","Time to first response","#2d9d78")}`)};
