 <section class="notes-summary" aria-label="Study guide summary"><div class="notes-summary-card"><span class="notes-summary-icon">${ic("notes")}</span><div><b>${S.notes.length}</b><span>Total study notes</span></div></div><div class="notes-summary-card"><span class="notes-summary-icon">✦</span><div><b>${concepts}</b><span>Key concepts</span></div></div><div class="notes-summary-card"><span class="notes-summary-icon">Aa</span><div><b>${definitions}</b><span>Definitions</span></div></div><div class="notes-summary-card"><span class="notes-summary-icon">✓</span><div><b>${reviewCount}</b><span>Marked reviewed</span></div></div></section>
