 if(item.loading)return `<div class="whywrong-loading" role="status"><span class="whywrong-spinner"></span><div><b>Building your explanation…</b><small>Checking the linked lecture passage and source material.</small></div></div>`;
 if(item.error)return `<div class="whywrong-error" role="alert"><b>Couldn't load the explanation.</b><span>${esc(item.error)}</span><button class="btn" data-why-wrong="${esc(q.id)}">Try again</button></div>`;
